<?php
require __DIR__.'/config/config.php';
$books = db()->query('SELECT b.*, c.name category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.is_active=1 ORDER BY b.id DESC')->fetchAll();
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cửa hàng - Nhà Sách Trí Tuệ</title><link rel="stylesheet" href="<?= BASE_URL ?>/style.css"></head><body><header class="topbar"><strong>NHÀ SÁCH TRÍ TUỆ</strong><span><?php if (!empty($_SESSION['customer'])): ?>Xin chào <?= e($_SESSION['customer']['name']) ?> · <a href="<?= BASE_URL ?>/cart.php">Giỏ hàng</a> · <a href="<?= BASE_URL ?>/customer-logout.php">Đăng xuất</a><?php else: ?><a href="<?= BASE_URL ?>/customer-login.php">Đăng nhập</a> · <a href="<?= BASE_URL ?>/customer-register.php">Đăng ký</a><?php endif; ?></span></header><main class="container"><h1>Sách nổi bật</h1><div class="book-grid"><?php foreach ($books as $book): ?><article class="book-card"><div class="book-cover">📖</div><h2><?= e($book['title']) ?></h2><p><?= e($book['author']) ?> · <?= e($book['category_name']) ?></p><b><?= number_format((float) $book['price'],0,',','.') ?>đ</b><span class="muted"> · Còn <?= (int) $book['stock_quantity'] ?></span><form method="post" action="<?= BASE_URL ?>/cart.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="book_id" value="<?= $book['id'] ?>"><input type="hidden" name="action" value="add"><button>Thêm vào giỏ</button></form></article><?php endforeach; ?></div></main></body></html>
